package com._8x8.herd.device_logs.processor.queue;

import com._8x8.herd.device_logs.processor.config.ProcessorProperties;
import com._8x8.herd.device_logs.processor.indexing.RecordIndexer;
import com._8x8.herd.device_logs.processor.indexing.UploadedObject;

import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import java.util.concurrent.CompletableFuture;
import java.util.stream.IntStream;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.context.SmartLifecycle;
import software.amazon.awssdk.services.sqs.SqsClient;
import software.amazon.awssdk.services.sqs.model.BatchResultErrorEntry;
import software.amazon.awssdk.services.sqs.model.DeleteMessageBatchRequestEntry;
import software.amazon.awssdk.services.sqs.model.DeleteMessageBatchResponse;
import software.amazon.awssdk.services.sqs.model.Message;

/**
 * Long-polls the upload queue on one thread and deletes a message only once every record in it is indexed. A message
 * that is not deleted comes back after the visibility timeout, and the queue's redrive policy moves it to the DLQ, so
 * nothing here sends anywhere. A stop lets the receive in progress return, finishes that batch, then stops polling.
 */
public class QueuePoller implements SmartLifecycle {

    private static final Logger LOG = LoggerFactory.getLogger(QueuePoller.class);

    private final SqsClient sqs;
    private final RecordIndexer indexer;
    private final ProcessorProperties.Queue queue;
    private final Duration retryDelay;
    private final S3EventParser parser = new S3EventParser();
    private final Object lock = new Object();
    private boolean running;
    private CompletableFuture<Void> stopped = CompletableFuture.completedFuture(null);

    /**
     * @param retryDelay how long to wait after a failed receive, so a queue outage doesn't spin the loop
     */
    public QueuePoller(SqsClient sqs, RecordIndexer indexer, ProcessorProperties.Queue queue, Duration retryDelay) {
        this.sqs = sqs;
        this.indexer = indexer;
        this.queue = queue;
        this.retryDelay = retryDelay;
    }

    /**
     * Receives one batch, indexes it and deletes the messages that are done.
     *
     * @return false if the receive failed
     */
    boolean pollOnce() {
        List<Message> messages;
        try {
            messages = sqs.receiveMessage(request -> request.queueUrl(queue.url()).maxNumberOfMessages(queue.maxMessages()).waitTimeSeconds((int) queue.waitTime().toSeconds()).visibilityTimeout((int) queue.visibilityTimeout().toSeconds())).messages();
        } catch (RuntimeException e) {
            LOG.warn("Receive from the queue failed, trying again in {}", retryDelay, e);
            return false;
        }
        List<Message> done = new ArrayList<>();
        for (Message message : messages) {
            if (handle(message)) {
                done.add(message);
            }
        }
        if (!done.isEmpty()) {
            delete(done);
        }
        return true;
    }

    private boolean handle(Message message) {
        Optional<S3Event> event = parser.parse(message.body());
        if (event.isEmpty()) {
            LOG.warn("Message {} is not an S3 event, leaving it on the queue", message.messageId());
            return false;
        }
        if (!(event.get() instanceof S3Event.ObjectsCreated created)) {
            LOG.info("Deleting S3's test event, message {}", message.messageId());
            return true;
        }
        int done = 0;
        for (UploadedObject object : created.objects()) {
            if (index(object)) {
                done++;
            }
        }
        if (done < created.objects().size()) {
            LOG.warn("Message {} left on the queue, {} of {} records indexed", message.messageId(), done, created.objects().size());
            return false;
        }
        return true;
    }

    private boolean index(UploadedObject object) {
        try {
            return indexer.index(object).done();
        } catch (RuntimeException e) {
            // The indexer turns expected failures into an outcome, so this is a bug or a broken client. The rest of the
            // batch still runs.
            LOG.warn("Not indexed {}: unexpected failure", object.key(), e);
            return false;
        }
    }

    private void delete(List<Message> messages) {
        // An entry's id only has to be unique in the batch, so its position is enough.
        List<DeleteMessageBatchRequestEntry> entries = IntStream.range(0, messages.size()).mapToObj(i -> DeleteMessageBatchRequestEntry.builder().id(Integer.toString(i)).receiptHandle(messages.get(i).receiptHandle()).build()).toList();
        DeleteMessageBatchResponse response;
        try {
            response = sqs.deleteMessageBatch(request -> request.queueUrl(queue.url()).entries(entries));
        } catch (RuntimeException e) {
            LOG.warn("Delete of {} messages failed, they come back and their rows already exist", messages.size(), e);
            return;
        }
        for (BatchResultErrorEntry failed : response.failed()) {
            LOG.warn("Delete of message {} failed, it comes back and its rows already exist: {} {}", messages.get(Integer.parseInt(failed.id())).messageId(), failed.code(), failed.message());
        }
    }

    private void poll() {
        while (isRunning()) {
            boolean received;
            try {
                received = pollOnce();
            } catch (RuntimeException e) {
                // A bug, not a queue problem, but the thread must not end while the pod looks healthy.
                LOG.warn("Poll failed unexpectedly, trying again in {}", retryDelay, e);
                received = false;
            }
            if (!received) {
                waitBeforeRetry();
            }
        }
    }

    private void waitBeforeRetry() {
        synchronized (lock) {
            try {
                // A stop wakes this wait early.
                if (running) {
                    lock.wait(retryDelay.toMillis());
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                running = false;
            }
        }
    }

    @Override
    public void start() {
        while (true) {
            CompletableFuture<Void> previous;
            synchronized (lock) {
                if (running) {
                    return;
                }
                if (stopped.isDone()) {
                    running = true;
                    CompletableFuture<Void> finished = new CompletableFuture<>();
                    stopped = finished;
                    new Thread(() -> {
                        try {
                            poll();
                        } finally {
                            finished.complete(null);
                        }
                    }, "queue-poller").start();
                    return;
                }
                previous = stopped;
            }
            // A stop returns while the old thread may still be in a receive. Waiting for it here, outside the lock so
            // that thread can finish, keeps a restart from leaving two threads polling.
            previous.join();
        }
    }

    @Override
    public void stop() {
        requestStop().join();
    }

    @Override
    public void stop(Runnable callback) {
        requestStop().thenRun(callback);
    }

    private CompletableFuture<Void> requestStop() {
        synchronized (lock) {
            running = false;
            lock.notifyAll();
            return stopped;
        }
    }

    @Override
    public boolean isRunning() {
        synchronized (lock) {
            return running;
        }
    }

    @Override
    public boolean isAutoStartup() {
        return queue.polling();
    }
}

